import{g as a,ad as e,r as n,A as t}from"./chunks/framework.BdL874pW.js";const u=JSON.parse('{"title":"useCall","description":"","frontmatter":{},"headers":[],"relativePath":"docs/data-fetching/use-call.md","filePath":"docs/data-fetching/use-call.md","lastUpdated":1789506983000}'),c={name:"docs/data-fetching/use-call.md"};function o(p,s,l,d,r,i){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="usecall" tabindex="-1">useCall <a class="header-anchor" href="#usecall" aria-label="Permalink to “useCall”">​</a></h1><p><code>useCall</code>, <code>useDoc</code>, <code>useList</code>, <code>useDoctype</code> and <code>useNewDoc</code> are the recommended data-fetching layer for new code. If you&#39;re maintaining an app still on the older resource API, see <a href="./resource">Resources</a> — it stays fully supported through <code>1.x</code>.</p><p><code>useCall</code> calls a whitelisted Frappe method or a REST endpoint and gives you back a reactive object with the response, loading and error state.</p><h2 id="basic-example" tabindex="-1">Basic example <a class="header-anchor" href="#basic-example" aria-label="Permalink to “Basic example”">​</a></h2><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ping.reload()</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> :loading</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ping.loading</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx"> Ping </span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">pre</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">{{ ping.data }}</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">pre</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useCall</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> ping</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/method/ping</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>By default the request fires immediately and uses <code>GET</code>.</p><h2 id="submitting-with-params" tabindex="-1">Submitting with params <a class="header-anchor" href="#submitting-with-params" aria-label="Permalink to “Submitting with params”">​</a></h2><p>Set <code>method</code> and call <code>submit()</code> for anything that isn&#39;t a plain <code>GET</code>:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useCall</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> renameTodo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/method/frappe.client.rename_doc</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  method</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">POST</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  immediate</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> false</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">async</span><span class="s_50ecpt"> function</span><span class="s_indoxt"> rename</span><span class="s_13ahmt">(</span><span class="s_fsg3al">name</span><span class="s_1jjt6x">,</span><span class="s_fsg3al"> newName</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_22m8k2"> renameTodo</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">    doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    old_name</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> name</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    new_name</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> newName</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><ul><li><code>url</code> — the endpoint to call. A REST path or a whitelisted method dotted path. Accepts a <code>Ref&lt;string&gt;</code> for a URL that changes reactively.</li><li><code>method</code> — the HTTP method: <code>&#39;GET&#39; | &#39;POST&#39; | &#39;PUT&#39; | &#39;DELETE&#39;</code>. Defaults to <code>&#39;GET&#39;</code>.</li><li><code>params</code> — the request params. Either a plain object, or a function returning one, read fresh on every request — use the function form so reactive values inside are re-read on each call.</li><li><code>immediate</code> — fire the first request automatically when <code>useCall</code> is set up. Defaults to <code>true</code>.</li><li><code>refetch</code> — automatically fire a new request whenever a reactive <code>url</code> or <code>params</code> dependency changes. Defaults to <code>false</code>.</li><li><code>baseUrl</code> — prefix prepended to <code>url</code>. Useful when the Frappe site isn&#39;t served from the same origin as the frontend.</li><li><code>initialData</code> — the value <code>data</code> holds before the first response arrives.</li><li><code>cacheKey</code> — a string, or array of primitives, that persists the response in memory and IndexedDB under that key. A second <code>useCall</code> with the same <code>cacheKey</code> shows the cached value immediately while it refetches in the background.</li><li><code>staleOnError</code> — when <code>true</code> and <code>cacheKey</code> is set, a failed refetch keeps showing the last cached <code>data</code> instead of clearing it. Does not apply when the failure is a Frappe error response (<code>FrappeResponseError</code>) — that still clears the cache. Defaults to <code>false</code>.</li><li><code>transform</code> — receives the raw response data and returns the value <code>data</code> should hold. Return <code>undefined</code> to leave the response untouched.</li><li><code>beforeSubmit</code> — runs before a <code>submit()</code> call sends its request. Use it for side effects like clearing a previous validation message; a normal return does not stop the request from being sent. If it throws, the request is not sent and <code>submit()</code> rejects.</li><li><code>onSuccess</code> — called with the response data after a successful request.</li><li><code>onError</code> — called with the error after a failed request.</li></ul><h2 id="return-value" tabindex="-1">Return value <a class="header-anchor" href="#return-value" aria-label="Permalink to “Return value”">​</a></h2><ul><li><code>data</code> — the response data, or <code>null</code> before the first successful response.</li><li><code>error</code> — the error from the last request, or <code>null</code>.</li><li><code>loading</code> (alias <code>isFetching</code>) — <code>true</code> while a request is in flight.</li><li><code>isFinished</code> — <code>true</code> once the current request has settled, either way.</li><li><code>params</code> — the params that were sent with the last request.</li><li><code>url</code> — the fully resolved URL, including <code>baseUrl</code> and, for <code>GET</code> requests, the serialized query string.</li><li><code>promise</code> — the in-flight request&#39;s promise. Resolves (it never rejects) once the request settles, whether it succeeded or failed — check <code>error</code> after awaiting it.</li><li><code>canAbort</code> — <code>true</code> while a request that can still be aborted is in flight.</li><li><code>aborted</code> — <code>true</code> if the last request was aborted.</li><li><code>execute()</code> (aliases <code>fetch()</code>, <code>reload()</code>) — fires a request using the current <code>params</code>, ignoring <code>immediate</code>/<code>refetch</code>. Resolves with the response data, or with <code>null</code> when the request fails; read <code>error</code> after awaiting it.</li><li><code>submit(params?)</code> — runs <code>beforeSubmit</code>, then sends a request with the given params (or the configured <code>params</code> if omitted). Resolves with the response data, or <strong>rejects</strong> with the error. It never settles on a request built before it; it settles on one that carried its own params, or on a later one that superseded it. Under <code>refetch: true</code> that request can be the one the params change already triggered; see <a href="#refetch-and-submit"><code>refetch</code> and <code>submit</code></a>.</li><li><code>reset()</code> — clears any params set by a previous <code>submit()</code> call.</li><li><code>abort()</code> — aborts the in-flight request.</li></ul><h3 id="refetch-and-submit" tabindex="-1"><code>refetch</code> and <code>submit</code> <a class="header-anchor" href="#refetch-and-submit" aria-label="Permalink to “refetch and submit”">​</a></h3><p>With <code>refetch: true</code>, a params change sends a request on its own. <code>submit()</code> waits for that request instead of adding one, and sends the request itself when the change triggered nothing — a second <code>submit()</code> with the same object, a <code>GET</code> whose params build the same URL, or a <code>submit()</code> with no argument at all.</p><p>Dispatch order decides which request is whose. A request reads the params when it is built, so one built after <code>submit()</code> assigned its params carries them and is that submit&#39;s request. One built before is not, even if it is still in flight, and the submit sends its own once that one settles.</p><p>Two things follow from <code>refetch</code> and <code>submit</code> sharing one request slot:</p><ul><li>Two <code>submit()</code> calls in the same tick become <strong>one</strong> request, carrying the params of the later call. Both promises resolve with that one response.</li><li>A params change supersedes the request in flight: the new request aborts the old one, and both callers resolve with the superseding response.</li></ul><p>Each composable instance has one request slot. When concurrent writes must not share one, give each its own <code>useCall</code>, or use <code>useDoc</code>, whose write methods are isolated per submit.</p><p><code>execute</code>/<code>fetch</code>/<code>reload</code> are one function under three names, and <code>loading</code>/<code>isFetching</code> one ref under two. v1 keeps every alias: apps use all of them, and dropping a name buys nothing. The docs use <code>reload()</code> and <code>loading</code>. This is the only place the library publishes two names for one thing.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to “Errors”">​</a></h2><p><strong>Actions reject, reads resolve.</strong> A failed write rejects, so a caller that does not handle the failure never runs its success path. A failed read resolves, so a template can keep rendering the last value and show <code>error</code> instead.</p><table tabindex="0"><thead><tr><th>Call</th><th>On failure</th></tr></thead><tbody><tr><td><code>submit()</code></td><td>rejects</td></tr><tr><td><code>doc.setValue.submit()</code>, <code>doc.delete.submit()</code>, a <code>useDoc</code> <code>methods:</code> member</td><td>rejects</td></tr><tr><td><code>execute()</code>, <code>fetch()</code>, <code>reload()</code>, <code>useList</code> <code>reload()</code></td><td>resolves, sets <code>error</code></td></tr></tbody></table><p>Every one of them sets <code>error</code> and calls <code>onError</code>, whether it rejects or not.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_50ecpt">try</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_22m8k2"> renameTodo</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">old_name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">todo-1</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> new_name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">todo-2</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_22m8k2">  toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">success</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Renamed</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_50ecpt"> catch</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">error</span><span class="s_13ahmt">(</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">message</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><h3 id="which-error-class" tabindex="-1">Which error you get <a class="header-anchor" href="#which-error-class" aria-label="Permalink to “Which error you get”">​</a></h3><p>Which one you get depends on the API that made the request, not on the failure. All three are plain <code>Error</code> objects:</p><table tabindex="0"><thead><tr><th>API</th><th>Error</th><th>Kind</th><th>Extra fields</th></tr></thead><tbody><tr><td><code>useCall</code>, <code>useDoc</code>, <code>useList</code>, <code>useDoctype</code>, <code>useNewDoc</code></td><td><a href="./../other/utilities#frapperesponseerror"><code>FrappeResponseError</code></a></td><td>class</td><td><code>title</code>, <code>type</code>, <code>exception</code>, <code>indicator</code></td></tr><tr><td><code>call</code>, <code>frappeRequest</code>, <code>createResource</code> and the other v1 resources</td><td><a href="./../other/utilities#frapperequesterror"><code>FrappeResourceError</code></a></td><td>type only</td><td><code>messages</code>, <code>exc_type</code>, <code>exc</code>, <code>status</code>, <code>response</code></td></tr><tr><td><code>upload</code>, <code>useFileUpload</code>, <code>FileUploadHandler</code></td><td><a href="./../other/utilities#uploaderror"><code>UploadError</code></a></td><td>class</td><td><code>kind</code>, <code>status</code>, <code>messages</code>, <code>response</code></td></tr></tbody></table><p>The two Frappe errors stay separate on purpose: the v2 composables read the parsed error page (<code>title</code>, <code>indicator</code>), and the resource layer keeps the raw transport fields (<code>status</code>, <code>response</code>). Each is named for the layer that raises it; both are server responses, so request versus response named nothing.</p><p>The <code>Kind</code> column decides how you narrow a catch block. <code>FrappeResponseError</code> and <code>UploadError</code> are classes, so <code>instanceof</code> works:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_50ecpt">if</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_2ekfrt"> instanceof</span><span class="s_euu481"> FrappeResponseError</span><span class="s_13ahmt">)</span><span class="s_22m8k2"> console</span><span class="s_1jjt6x">.</span><span class="s_indoxt">log</span><span class="s_13ahmt">(</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">title</span><span class="s_13ahmt">)</span></span></code></pre></div><p><code>FrappeResourceError</code> is a TypeScript type over a plain <code>Error</code>, not a constructor. There is no value to test, so <code>error instanceof FrappeResourceError</code> does not compile. Check the field you need instead:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_50ecpt">if</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">exc_type</span><span class="s_50ecpt"> ===</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">PermissionError</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_indoxt"> showPermissionMessage</span><span class="s_13ahmt">()</span></span></code></pre></div><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to “Caching”">​</a></h2><p>Pass <code>cacheKey</code> to persist the response. The cached value is read from IndexedDB and shown immediately on the next <code>useCall</code> with the same key, while a fresh request runs in the background and replaces it once it resolves.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todo</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/method/frappe.client.get</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  params</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">todo-1</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  cacheKey</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">todo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">todo-1</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div>`,36)])])}const _=a(c,[["render",o]]);export{u as __pageData,_ as default};
